import { countDueListeningReviews } from '../../services/listeningProgress';
import { AudioLines, BookOpen, CheckCircle2, CircleHelp, Headphones, Pause, Play, RotateCcw, Search, Settings2, Volume2 } from 'lucide-react';

type ListeningItem = {
  id: string; hsk: number; topic: string; title: string; situation: string;
  hanzi: string; pinyin: string; meaning: string; question: string;
  options: string[]; answer: number; note: string;
};
const lessons: ListeningItem[] = [
  { id:'greeting',hsk:1,topic:'Giao tiếp',title:'Chào hỏi và làm quen',situation:'Lần đầu gặp bạn mới',hanzi:'你好！我叫林娜。你叫什么名字？\n我叫小明，很高兴认识你。',pinyin:'Nǐ hǎo! Wǒ jiào Lín Nà. Nǐ jiào shénme míngzi?\nWǒ jiào Xiǎo Míng, hěn gāoxìng rènshi nǐ.',meaning:'Xin chào! Mình tên là Lina. Bạn tên gì?\nMình tên Tiểu Minh, rất vui được làm quen với bạn.',question:'小明 nói gì khi làm quen?',options:['Rất vui được làm quen','Bạn đi đâu vậy?','Hôm nay thứ mấy?'],answer:0,note:'很高兴认识你 (hěn gāoxìng rènshi nǐ) là cách nói tự nhiên khi gặp người mới.'},
  { id:'nationality',hsk:1,topic:'Giao tiếp',title:'Bạn đến từ đâu?',situation:'Hỏi quê quán',hanzi:'你是哪国人？\n我是越南人，你呢？\n我是中国人。',pinyin:'Nǐ shì nǎ guó rén?\nWǒ shì Yuènán rén, nǐ ne?\nWǒ shì Zhōngguó rén.',meaning:'Bạn là người nước nào?\nMình là người Việt Nam, còn bạn?\nMình là người Trung Quốc.',question:'Người thứ hai đến từ nước nào?',options:['Trung Quốc','Việt Nam','Singapore'],answer:1,note:'越南人 là người Việt Nam; 中国人 là người Trung Quốc.'},
  { id:'numbers',hsk:1,topic:'Đời sống',title:'Số điện thoại',situation:'Trao đổi số liên lạc',hanzi:'你的电话号码是多少？\n是一三八，零二六五，九八七四。',pinyin:'Nǐ de diànhuà hàomǎ shì duōshao?\nShì yī sān bā, líng èr liù wǔ, jiǔ bā qī sì.',meaning:'Số điện thoại của bạn là bao nhiêu?\nLà 138-0265-9874.',question:'Người nói đang cung cấp thông tin gì?',options:['Địa chỉ nhà','Số điện thoại','Giờ hẹn'],answer:1,note:'电话号码 là số điện thoại. Khi đọc số điện thoại tiếng Trung, từng chữ số thường được đọc riêng.'},
  { id:'time',hsk:1,topic:'Đời sống',title:'Hỏi giờ và hẹn gặp',situation:'Hẹn gặp ở quán cà phê',hanzi:'现在几点？\n两点十分。我们三点在咖啡店见，好吗？\n好，三点见。',pinyin:'Xiànzài jǐ diǎn?\nLiǎng diǎn shí fēn. Wǒmen sān diǎn zài kāfēidiàn jiàn, hǎo ma?\nHǎo, sān diǎn jiàn.',meaning:'Bây giờ là mấy giờ?\nHai giờ mười. Ba giờ chúng ta gặp ở quán cà phê nhé?\nĐược, hẹn gặp lúc ba giờ.',question:'Họ hẹn gặp lúc mấy giờ?',options:['2 giờ 10','2 giờ 30','3 giờ'],answer:2,note:'三点 (sān diǎn) là 3 giờ; 咖啡店 là quán cà phê.'},
  { id:'food-order',hsk:1,topic:'Ăn uống',title:'Gọi món ở quán ăn',situation:'Gọi đồ ăn và đồ uống',hanzi:'您好，您要吃什么？\n我要一碗米饭和一杯茶。\n好的，请稍等。',pinyin:'Nín hǎo, nín yào chī shénme?\nWǒ yào yì wǎn mǐfàn hé yì bēi chá.\nHǎo de, qǐng shāo děng.',meaning:'Xin chào, quý khách muốn ăn gì?\nTôi muốn một bát cơm và một tách trà.\nĐược ạ, xin chờ một chút.',question:'Khách gọi món gì?',options:['Mì và cà phê','Cơm và trà','Bánh bao và nước'],answer:1,note:'一碗米饭 là một bát cơm; 一杯茶 là một tách trà.'},
  { id:'shopping',hsk:2,topic:'Mua sắm',title:'Hỏi giá và mặc cả',situation:'Mua áo ở cửa hàng',hanzi:'这件衣服多少钱？\n一百二十块。\n有点儿贵，能便宜一点儿吗？\n那就一百块吧。',pinyin:'Zhè jiàn yīfu duōshao qián?\nYì bǎi èrshí kuài.\nYǒudiǎnr guì, néng piányi yìdiǎnr ma?\nNà jiù yì bǎi kuài ba.',meaning:'Bộ quần áo này bao nhiêu tiền?\n120 tệ.\nHơi đắt, rẻ hơn một chút được không?\nVậy lấy 100 tệ nhé.',question:'Giá cuối cùng là bao nhiêu?',options:['80 tệ','100 tệ','120 tệ'],answer:1,note:'块 (kuài) là cách nói khẩu ngữ phổ biến của đơn vị nhân dân tệ; 有点儿贵 nghĩa là hơi đắt.'},
  { id:'directions',hsk:2,topic:'Đi lại',title:'Hỏi đường đến ga tàu',situation:'Tìm đường trong thành phố',hanzi:'请问，火车站怎么走？\n一直往前走，在第二个路口左转。\n远吗？\n不远，走十分钟就到了。',pinyin:'Qǐngwèn, huǒchēzhàn zěnme zǒu?\nYìzhí wǎng qián zǒu, zài dì èr ge lùkǒu zuǒ zhuǎn.\nYuǎn ma?\nBù yuǎn, zǒu shí fēnzhōng jiù dào le.',meaning:'Xin hỏi đi đến ga tàu thế nào?\nĐi thẳng, rẽ trái ở ngã tư thứ hai.\nCó xa không?\nKhông xa, đi bộ mười phút là tới.',question:'Người hỏi cần đi bộ khoảng bao lâu?',options:['5 phút','10 phút','20 phút'],answer:1,note:'一直往前走 là đi thẳng; 左转 là rẽ trái; 路口 là ngã giao đường.'},
  { id:'weather',hsk:2,topic:'Đời sống',title:'Dự báo thời tiết',situation:'Lên kế hoạch đi chơi',hanzi:'明天天气怎么样？\n天气预报说会下雨，气温也会下降。\n那我们还是带上雨伞吧。',pinyin:'Míngtiān tiānqì zěnmeyàng?\nTiānqì yùbào shuō huì xiàyǔ, qìwēn yě huì xiàjiàng.\nNà wǒmen háishi dài shàng yǔsǎn ba.',meaning:'Thời tiết ngày mai thế nào?\nDự báo nói sẽ mưa, nhiệt độ cũng sẽ giảm.\nVậy chúng ta vẫn nên mang ô.',question:'Vì sao họ quyết định mang ô?',options:['Trời sẽ mưa','Trời quá nóng','Họ muốn đi bơi'],answer:0,note:'天气预报 là dự báo thời tiết; 下雨 là mưa; 雨伞 là ô/dù.'},
  { id:'weekend',hsk:2,topic:'Đời sống',title:'Kế hoạch cuối tuần',situation:'Rủ bạn đi xem phim',hanzi:'周末你有什么安排？\n星期六我得复习，星期天可以一起去看电影。\n好啊，我们上午还是下午去？',pinyin:'Zhōumò nǐ yǒu shénme ānpái?\nXīngqīliù wǒ děi fùxí, xīngqītiān kěyǐ yìqǐ qù kàn diànyǐng.\nHǎo a, wǒmen shàngwǔ háishi xiàwǔ qù?',meaning:'Cuối tuần bạn có kế hoạch gì?\nThứ Bảy mình phải ôn bài, Chủ nhật có thể cùng đi xem phim.\nĐược đó, chúng ta đi buổi sáng hay buổi chiều?',question:'Ngày nào người nói có thể đi xem phim?',options:['Thứ Sáu','Thứ Bảy','Chủ nhật'],answer:2,note:'安排 là kế hoạch/sắp xếp; 复习 là ôn tập; 一起 là cùng nhau.'},
  { id:'hotel',hsk:2,topic:'Du lịch',title:'Nhận phòng khách sạn',situation:'Làm thủ tục ở quầy lễ tân',hanzi:'您好，我预订了一个双人房。\n请问您贵姓？\n我姓阮。这是我的护照。\n好的，您的房间在八楼。',pinyin:'Nín hǎo, wǒ yùdìng le yí ge shuāngrén fáng.\nQǐngwèn nín guìxìng?\nWǒ xìng Ruǎn. Zhè shì wǒ de hùzhào.\nHǎo de, nín de fángjiān zài bā lóu.',meaning:'Xin chào, tôi đã đặt phòng đôi.\nXin hỏi quý khách họ gì?\nTôi họ Nguyễn. Đây là hộ chiếu của tôi.\nVâng, phòng của quý khách ở tầng tám.',question:'Phòng của khách ở tầng mấy?',options:['Tầng 2','Tầng 6','Tầng 8'],answer:2,note:'预订 là đặt trước; 双人房 là phòng đôi; 护照 là hộ chiếu.'},
  { id:'transport',hsk:3,topic:'Đi lại',title:'Chọn phương tiện đi lại',situation:'So sánh tàu điện và taxi',hanzi:'从这里到火车站，坐地铁比较方便。\n可是我带着两个大行李箱。\n那坐出租车可能更合适，不过高峰时间会堵车。',pinyin:'Cóng zhèlǐ dào huǒchēzhàn, zuò dìtiě bǐjiào fāngbiàn.\nKěshì wǒ dàizhe liǎng ge dà xínglǐxiāng.\nNà zuò chūzūchē kěnéng gèng héshì, búguò gāofēng shíjiān huì dǔchē.',meaning:'Từ đây đến ga tàu, đi tàu điện ngầm khá thuận tiện.\nNhưng tôi mang theo hai vali lớn.\nVậy taxi có lẽ phù hợp hơn, nhưng giờ cao điểm sẽ tắc đường.',question:'Điểm bất tiện của taxi vào giờ cao điểm là gì?',options:['Không có chỗ để hành lý','Có thể tắc đường','Không đi đến ga'],answer:1,note:'高峰时间 là giờ cao điểm; 堵车 là tắc đường; 行李箱 là vali.'},
  { id:'doctor',hsk:3,topic:'Sức khỏe',title:'Mô tả triệu chứng khi đi khám',situation:'Trao đổi với bác sĩ',hanzi:'你哪里不舒服？\n我从昨天晚上开始头疼，还有点儿发烧。\n咳嗽吗？\n不咳嗽，就是觉得很累。',pinyin:'Nǐ nǎlǐ bù shūfu?\nWǒ cóng zuótiān wǎnshang kāishǐ tóuténg, hái yǒudiǎnr fāshāo.\nKésou ma?\nBù késou, jiùshì juéde hěn lèi.',meaning:'Bạn thấy khó chịu ở đâu?\nTừ tối qua tôi bắt đầu đau đầu, còn hơi sốt.\nCó ho không?\nKhông ho, chỉ cảm thấy rất mệt.',question:'Người bệnh có triệu chứng nào?',options:['Đau đầu và hơi sốt','Đau bụng và ho','Đau chân'],answer:0,note:'头疼 là đau đầu; 发烧 là sốt; 咳嗽 là ho. Đây là đoạn hội thoại ngôn ngữ học tập, không phải tư vấn y tế.'},
  { id:'rent',hsk:3,topic:'Đời sống',title:'Tìm phòng thuê',situation:'Trao đổi với chủ nhà',hanzi:'这套房子离地铁站远吗？\n走路大概十分钟。附近有超市和公园。\n房租包括水电费吗？\n水费包括，电费要另外付。',pinyin:'Zhè tào fángzi lí dìtiězhàn yuǎn ma?\nZǒulù dàgài shí fēnzhōng. Fùjìn yǒu chāoshì hé gōngyuán.\nFángzū bāokuò shuǐdiànfèi ma?\nShuǐfèi bāokuò, diànfèi yào lìngwài fù.',meaning:'Căn hộ này có xa ga tàu điện ngầm không?\nĐi bộ khoảng mười phút. Gần đây có siêu thị và công viên.\nTiền thuê có gồm điện nước không?\nCó tiền nước, tiền điện phải trả riêng.',question:'Khoản nào không bao gồm trong tiền thuê?',options:['Tiền nước','Tiền điện','Cả hai khoản'],answer:1,note:'房租 là tiền thuê nhà; 包括 là bao gồm; 另外付 là trả riêng.'},
  { id:'work',hsk:3,topic:'Công việc',title:'Trao đổi lịch họp',situation:'Sắp xếp lịch với đồng nghiệp',hanzi:'下午的会议提前到两点半了，你能参加吗？\n可以，我会把报告准备好。\n记得把文件发给大家。\n没问题，我中午以前发出去。',pinyin:'Xiàwǔ de huìyì tíqián dào liǎng diǎn bàn le, nǐ néng cānjiā ma?\nKěyǐ, wǒ huì bǎ bàogào zhǔnbèi hǎo.\nJìde bǎ wénjiàn fā gěi dàjiā.\nMéi wèntí, wǒ zhōngwǔ yǐqián fā chūqù.',meaning:'Cuộc họp chiều được chuyển sớm lên 2 giờ 30, bạn tham gia được không?\nĐược, tôi sẽ chuẩn bị xong báo cáo.\nNhớ gửi tài liệu cho mọi người.\nKhông vấn đề, tôi sẽ gửi trước buổi trưa.',question:'Người nói hứa gửi tài liệu khi nào?',options:['Sau cuộc họp','Trước buổi trưa','Ngày mai'],answer:1,note:'提前 là sớm hơn dự kiến; 参加 là tham gia; 以前 là trước thời điểm nào đó.'},
  { id:'study',hsk:3,topic:'Học tập',title:'Đăng ký khóa học',situation:'Hỏi về lớp tiếng Trung',hanzi:'我想报名周末的汉语课。\n你学过汉语吗？\n学过一年，不过听力还不太好。\n那你可以先参加中级班的水平测试。',pinyin:'Wǒ xiǎng bàomíng zhōumò de Hànyǔ kè.\nNǐ xuéguo Hànyǔ ma?\nXuéguo yì nián, búguò tīnglì hái bú tài hǎo.\nNà nǐ kěyǐ xiān cānjiā zhōngjí bān de shuǐpíng cèshì.',meaning:'Tôi muốn đăng ký lớp tiếng Trung cuối tuần.\nBạn đã học tiếng Trung chưa?\nHọc một năm rồi, nhưng nghe vẫn chưa tốt lắm.\nVậy bạn có thể làm bài kiểm tra trình độ của lớp trung cấp trước.',question:'Kỹ năng nào người học nói là chưa tốt?',options:['Đọc','Nghe','Viết'],answer:1,note:'报名 là đăng ký; 听力 là kỹ năng nghe; 水平测试 là bài kiểm tra trình độ.'},
  { id:'delivery',hsk:3,topic:'Mua sắm',title:'Nhận hàng giao tận nhà',situation:'Gọi cho nhân viên giao hàng',hanzi:'您好，您的快递到了，请问您在家吗？\n我现在不在家，可以放在小区门口的快递柜里吗？\n可以，我给您发取件码。',pinyin:'Nín hǎo, nín de kuàidì dào le, qǐngwèn nín zài jiā ma?\nWǒ xiànzài bú zài jiā, kěyǐ fàng zài xiǎoqū ménkǒu de kuàidì guì lǐ ma?\nKěyǐ, wǒ gěi nín fā qǔjiànmǎ.',meaning:'Xin chào, bưu kiện của bạn đã đến, bạn có ở nhà không?\nBây giờ tôi không ở nhà, có thể để vào tủ nhận hàng ở cổng khu dân cư không?\nĐược, tôi sẽ gửi mã nhận hàng cho bạn.',question:'Người nhận muốn để bưu kiện ở đâu?',options:['Quầy lễ tân công ty','Tủ nhận hàng ở cổng khu dân cư','Nhà hàng xóm'],answer:1,note:'快递 là bưu kiện/chuyển phát; 快递柜 là tủ nhận hàng; 取件码 là mã nhận hàng.'},
  { id:'flight',hsk:4,topic:'Du lịch',title:'Thông báo ở sân bay',situation:'Nghe thông báo chuyến bay',hanzi:'各位旅客请注意，飞往上海的CA1234次航班将延迟三十分钟起飞。\n请旅客在登机口附近等候，并留意广播通知。',pinyin:'Gèwèi lǚkè qǐng zhùyì, fēi wǎng Shànghǎi de CA yī èr sān sì cì hángbān jiāng yánchí sānshí fēnzhōng qǐfēi.\nQǐng lǚkè zài dēngjīkǒu fùjìn děnghòu, bìng liúyì guǎngbō tōngzhī.',meaning:'Kính mời hành khách chú ý: chuyến bay CA1234 đi Thượng Hải sẽ khởi hành muộn 30 phút.\nVui lòng chờ gần cửa lên máy bay và chú ý thông báo phát thanh.',question:'Chuyến bay bị chậm bao lâu?',options:['15 phút','30 phút','60 phút'],answer:1,note:'航班 là chuyến bay; 延迟 là trì hoãn; 登机口 là cửa lên máy bay. Đây là tình huống mô phỏng được biên soạn, không phải thông báo sân bay thực.'},
  { id:'refund',hsk:4,topic:'Mua sắm',title:'Đổi trả sản phẩm',situation:'Trao đổi với bộ phận chăm sóc khách hàng',hanzi:'您好，我昨天收到的耳机有一边没有声音。\n很抱歉给您带来不便。您可以申请换货，请提供订单号。\n我已经准备好了，马上发给您。',pinyin:'Nín hǎo, wǒ zuótiān shōudào de ěrjī yǒu yì biān méiyǒu shēngyīn.\nHěn bàoqiàn gěi nín dàilái búbiàn. Nín kěyǐ shēnqǐng huànhuò, qǐng tígōng dìngdān hào.\nWǒ yǐjīng zhǔnbèi hǎo le, mǎshàng fā gěi nín.',meaning:'Xin chào, tai nghe tôi nhận hôm qua có một bên không có tiếng.\nRất xin lỗi vì sự bất tiện này. Bạn có thể yêu cầu đổi hàng, vui lòng cung cấp mã đơn hàng.\nTôi đã chuẩn bị rồi, sẽ gửi ngay cho bạn.',question:'Nhân viên đề nghị giải pháp nào?',options:['Hoàn toàn không hỗ trợ','Đổi hàng và cung cấp mã đơn','Tự sửa tai nghe'],answer:1,note:'换货 là đổi hàng; 订单号 là mã đơn hàng; 申请 là nộp yêu cầu.'},
  { id:'interview',hsk:4,topic:'Công việc',title:'Phỏng vấn xin việc',situation:'Nhà tuyển dụng hỏi kinh nghiệm',hanzi:'请介绍一下您以前的工作经验。\n我在一家贸易公司工作了三年，主要负责客户沟通和订单管理。\n您为什么想换工作？\n我希望有机会参与国际项目，进一步提高自己的能力。',pinyin:'Qǐng jièshào yíxià nín yǐqián de gōngzuò jīngyàn.\nWǒ zài yì jiā màoyì gōngsī gōngzuò le sān nián, zhǔyào fùzé kèhù gōutōng hé dìngdān guǎnlǐ.\nNín wèishénme xiǎng huàn gōngzuò?\nWǒ xīwàng yǒu jīhuì cānyù guójì xiàngmù, jìnyíbù tígāo zìjǐ de nénglì.',meaning:'Xin hãy giới thiệu kinh nghiệm làm việc trước đây.\nTôi làm ở một công ty thương mại ba năm, chủ yếu phụ trách giao tiếp khách hàng và quản lý đơn hàng.\nVì sao bạn muốn đổi việc?\nTôi hy vọng có cơ hội tham gia dự án quốc tế và nâng cao năng lực.',question:'Ứng viên phụ trách những việc gì?',options:['Thiết kế sản phẩm','Giao tiếp khách hàng và quản lý đơn hàng','Tuyển dụng nhân sự'],answer:1,note:'工作经验 là kinh nghiệm làm việc; 负责 là phụ trách; 进一步 là tiến thêm một bước/nâng cao hơn.'},
  { id:'environment',hsk:4,topic:'Xã hội',title:'Phân loại rác',situation:'Thông báo tại khu dân cư',hanzi:'为了保护环境，请大家按照规定分类投放垃圾。\n纸张和塑料瓶属于可回收物，剩菜剩饭应该放进厨余垃圾桶。\n谢谢大家的配合。',pinyin:'Wèile bǎohù huánjìng, qǐng dàjiā ànzhào guīdìng fēnlèi tóufàng lājī.\nZhǐzhāng hé sùliào píng shǔyú kě huíshōu wù, shèngcài shèngfàn yīnggāi fàng jìn chúyú lājītǒng.\nXièxie dàjiā de pèihé.',meaning:'Để bảo vệ môi trường, xin mọi người phân loại rác theo quy định.\nGiấy và chai nhựa thuộc loại có thể tái chế; thức ăn thừa nên bỏ vào thùng rác nhà bếp.\nCảm ơn mọi người đã hợp tác.',question:'Chai nhựa được xếp vào loại nào?',options:['Rác nhà bếp','Rác nguy hại','Vật liệu có thể tái chế'],answer:2,note:'可回收物 là vật có thể tái chế; 厨余垃圾 là rác nhà bếp/thức ăn thừa.'},
  { id:'remote-work',hsk:5,topic:'Công việc',title:'Làm việc từ xa',situation:'Thảo luận quy định của nhóm',hanzi:'实行远程办公以后，大家节省了通勤时间，但也更需要主动沟通。\n我们决定每周开一次项目会议，并通过共享文档及时更新进度。\n如果遇到问题，不要等到最后一刻才提出。',pinyin:'Shíxíng yuǎnchéng bàngōng yǐhòu, dàjiā jiéshěng le tōngqín shíjiān, dàn yě gèng xūyào zhǔdòng gōutōng.\nWǒmen juédìng měi zhōu kāi yí cì xiàngmù huìyì, bìng tōngguò gòngxiǎng wéndàng jíshí gēngxīn jìndù.\nRúguǒ yùdào wèntí, búyào děng dào zuìhòu yíkè cái tíchū.',meaning:'Sau khi áp dụng làm việc từ xa, mọi người tiết kiệm thời gian đi lại nhưng cũng cần chủ động giao tiếp hơn.\nChúng tôi quyết định họp dự án mỗi tuần một lần và cập nhật tiến độ kịp thời qua tài liệu dùng chung.\nNếu gặp vấn đề, đừng đợi đến phút cuối mới nêu ra.',question:'Nhóm sẽ cập nhật tiến độ bằng cách nào?',options:['Chỉ nói chuyện trực tiếp','Dùng tài liệu chia sẻ','Không cập nhật'],answer:1,note:'远程办公 là làm việc từ xa; 通勤 là đi lại giữa nhà và nơi làm; 进度 là tiến độ.'},
  { id:'learning-method',hsk:5,topic:'Học tập',title:'Thói quen học ngoại ngữ',situation:'Chia sẻ kinh nghiệm tự học',hanzi:'与其一次学习几个小时，不如把任务分成小块，每天坚持练习。\n听完一段材料以后，先尝试复述大意，再对照文本找出没听懂的地方。\n这样既能积累词汇，也能逐渐提高理解速度。',pinyin:'Yǔqí yí cì xuéxí jǐ ge xiǎoshí, bùrú bǎ rènwu fēn chéng xiǎo kuài, měitiān jiānchí liànxí.\nTīng wán yí duàn cáiliào yǐhòu, xiān chángshì fùshù dàyì, zài duìzhào wénběn zhǎochū méi tīng dǒng de dìfang.\nZhèyàng jì néng jīlěi cíhuì, yě néng zhújiàn tígāo lǐjiě sùdù.',meaning:'Thay vì học vài tiếng trong một lần, hãy chia nhiệm vụ thành phần nhỏ và kiên trì mỗi ngày.\nSau khi nghe một đoạn, thử kể lại ý chính trước, rồi đối chiếu văn bản để tìm chỗ chưa hiểu.\nCách này vừa tích lũy từ vựng vừa dần tăng tốc độ hiểu.',question:'Theo đoạn nghe, nên làm gì trước khi đối chiếu văn bản?',options:['Dịch từng chữ ngay','Thử kể lại ý chính','Bỏ qua đoạn khó'],answer:1,note:'复述大意 là kể lại ý chính; 对照文本 là đối chiếu với văn bản; 逐渐 là dần dần.'},
  { id:'city-life',hsk:5,topic:'Xã hội',title:'Sống ở thành phố lớn',situation:'Trao đổi về lựa chọn nơi ở',hanzi:'大城市提供了更多就业和学习机会，不过生活成本也相对较高。\n对刚毕业的年轻人来说，选择住在哪里，不仅要考虑工资，还要考虑通勤时间、公共服务和个人发展。',pinyin:'Dà chéngshì tígōng le gèng duō jiùyè hé xuéxí jīhuì, búguò shēnghuó chéngběn yě xiāngduì jiào gāo.\nDuì gāng bìyè de niánqīng rén lái shuō, xuǎnzé zhù zài nǎlǐ, bùjǐn yào kǎolǜ gōngzī, hái yào kǎolǜ tōngqín shíjiān, gōnggòng fúwù hé gèrén fāzhǎn.',meaning:'Thành phố lớn có nhiều cơ hội việc làm và học tập hơn, nhưng chi phí sinh hoạt cũng tương đối cao.\nVới người trẻ mới tốt nghiệp, chọn nơi ở không chỉ cần cân nhắc lương mà còn thời gian đi lại, dịch vụ công và phát triển cá nhân.',question:'Ngoài tiền lương, đoạn nghe khuyên cân nhắc điều gì?',options:['Thời gian đi lại và cơ hội phát triển','Chỉ diện tích căn hộ','Màu sắc của tòa nhà'],answer:0,note:'生活成本 là chi phí sinh hoạt; 不仅…还… là không chỉ… mà còn…; 个人发展 là phát triển cá nhân.'},
  { id:'culture',hsk:5,topic:'Văn hóa',title:'Văn hóa uống trà',situation:'Giới thiệu một nét sinh hoạt',hanzi:'在中国，喝茶不仅是一种饮食习惯，也常常与待客、交友和休息联系在一起。\n不同地区有不同的茶类和冲泡方式。了解这些习惯时，最好先观察当地人的做法，再礼貌地提出问题。',pinyin:'Zài Zhōngguó, hē chá bùjǐn shì yì zhǒng yǐnshí xíguàn, yě chángcháng yǔ dàikè, jiāoyǒu hé xiūxi liánxì zài yìqǐ.\nBùtóng dìqū yǒu bùtóng de chálèi hé chōngpào fāngshì. Liǎojiě zhèxiē xíguàn shí, zuìhǎo xiān guānchá dāngdì rén de zuòfǎ, zài lǐmào de tíchū wèntí.',meaning:'Ở Trung Quốc, uống trà không chỉ là thói quen ăn uống mà còn thường gắn với tiếp khách, kết bạn và nghỉ ngơi.\nCác vùng có loại trà và cách pha khác nhau. Khi tìm hiểu phong tục, nên quan sát cách người địa phương làm rồi lịch sự đặt câu hỏi.',question:'Cách tìm hiểu phong tục được khuyên là gì?',options:['Đánh giá ngay','Quan sát trước rồi hỏi lịch sự','Cho rằng mọi vùng giống nhau'],answer:1,note:'待客 là tiếp khách; 冲泡方式 là cách pha; 当地人 là người địa phương.'},
  { id:'news',hsk:6,topic:'Xã hội',title:'Đọc hiểu tin tức và số liệu',situation:'Nghe bản tin phân tích ngắn',hanzi:'一项调查显示，越来越多的城市居民开始选择公共交通或骑行出行。\n研究人员指出，这一变化与交通网络的完善、环保意识的提高以及停车成本的增加都有关系。\n不过，调查结果反映的是受访者的情况，并不一定适用于所有城市。',pinyin:'Yí xiàng diàochá xiǎnshì, yuèláiyuè duō de chéngshì jūmín kāishǐ xuǎnzé gōnggòng jiāotōng huò qíxíng chūxíng.\nYánjiū rényuán zhǐchū, zhè yí biànhuà yǔ jiāotōng wǎngluò de wánshàn, huánbǎo yìshí de tígāo yǐjí tíngchē chéngběn de zēngjiā dōu yǒu guānxi.\nBúguò, diàochá jiéguǒ fǎnyìng de shì shòufǎngzhě de qíngkuàng, bìng bù yídìng shìyòng yú suǒyǒu chéngshì.',meaning:'Một khảo sát cho thấy ngày càng nhiều cư dân thành thị chọn giao thông công cộng hoặc đi xe đạp.\nCác nhà nghiên cứu cho rằng sự thay đổi liên quan đến mạng lưới giao thông được cải thiện, ý thức môi trường tăng và chi phí đỗ xe cao hơn.\nTuy nhiên, kết quả phản ánh tình hình của người được khảo sát, không nhất thiết áp dụng cho mọi thành phố.',question:'Đoạn nghe lưu ý điều gì về kết quả khảo sát?',options:['Áp dụng cho mọi thành phố','Chỉ phản ánh người được khảo sát, không đại diện chắc chắn cho mọi nơi','Không liên quan đến giao thông'],answer:1,note:'调查显示 là khảo sát cho thấy; 受访者 là người được phỏng vấn/khảo sát; 适用于 là áp dụng cho.'},
  { id:'language',hsk:6,topic:'Học tập',title:'Ngôn ngữ và bối cảnh',situation:'Thảo luận cách hiểu một câu nói',hanzi:'理解一种语言，不能只依靠词典中的字面解释，还需要结合说话人的语气、双方的关系以及具体场景。\n同一句话在正式会议和朋友聊天时，可能产生不同的语用效果。\n因此，学习者应当把语言形式与真实交际情境联系起来。',pinyin:'Lǐjiě yì zhǒng yǔyán, bùnéng zhǐ yīkào cídiǎn zhōng de zìmiàn jiěshì, hái xūyào jiéhé shuōhuàrén de yǔqì, shuāngfāng de guānxi yǐjí jùtǐ chǎngjǐng.\nTóng yí jù huà zài zhèngshì huìyì hé péngyou liáotiān shí, kěnéng chǎnshēng bùtóng de yǔyòng xiàoguǒ.\nYīncǐ, xuéxízhě yīngdāng bǎ yǔyán xíngshì yǔ zhēnshí jiāojì qíngjìng liánxì qǐlái.',meaning:'Để hiểu một ngôn ngữ, không thể chỉ dựa vào nghĩa đen trong từ điển mà còn cần kết hợp ngữ điệu, quan hệ giữa hai bên và tình huống cụ thể.\nCùng một câu có thể tạo hiệu quả ngữ dụng khác nhau trong cuộc họp trang trọng và lúc trò chuyện với bạn bè.\nVì vậy, người học nên gắn hình thức ngôn ngữ với tình huống giao tiếp thực tế.',question:'Điều gì ngoài nghĩa từ điển giúp hiểu câu nói?',options:['Ngữ điệu, quan hệ và bối cảnh','Chỉ độ dài câu','Số lượng chữ Hán'],answer:0,note:'字面解释 là giải thích theo nghĩa đen; 语气 là ngữ điệu/thái độ; 语用效果 là hiệu quả ngữ dụng.'},

  { id:'morning-routine',hsk:1,topic:'Đời sống',title:'Một buổi sáng thường ngày',situation:'Kể về lịch sinh hoạt',hanzi:'我每天早上七点起床，先洗脸刷牙，再吃早饭。\n八点我坐公共汽车去学校。',pinyin:'Wǒ měitiān zǎoshang qī diǎn qǐchuáng, xiān xǐliǎn shuāyá, zài chī zǎofàn.\nBā diǎn wǒ zuò gōnggòng qìchē qù xuéxiào.',meaning:'Mỗi sáng tôi thức dậy lúc bảy giờ, rửa mặt đánh răng rồi ăn sáng.\nTám giờ tôi đi xe buýt đến trường.',question:'Người nói đi học bằng phương tiện gì?',options:['Tàu điện ngầm','Xe buýt','Xe đạp'],answer:1,note:'起床 là thức dậy; 先…再… diễn tả trình tự; 公共汽车 là xe buýt.'},
  { id:'family',hsk:1,topic:'Giao tiếp',title:'Giới thiệu gia đình',situation:'Nói về người thân',hanzi:'你家有几口人？\n我家有四口人：爸爸、妈妈、姐姐和我。\n你姐姐做什么工作？\n她是老师。',pinyin:'Nǐ jiā yǒu jǐ kǒu rén?\nWǒ jiā yǒu sì kǒu rén: bàba, māma, jiějie hé wǒ.\nNǐ jiějie zuò shénme gōngzuò?\nTā shì lǎoshī.',meaning:'Gia đình bạn có mấy người?\nNhà mình có bốn người: bố, mẹ, chị gái và mình.\nChị gái bạn làm nghề gì?\nChị ấy là giáo viên.',question:'Chị gái của người nói làm nghề gì?',options:['Bác sĩ','Giáo viên','Nhân viên văn phòng'],answer:1,note:'口 là lượng từ dùng để đếm thành viên gia đình; 姐姐 là chị gái.'},
  { id:'train-ticket',hsk:2,topic:'Du lịch',title:'Mua vé tàu',situation:'Hỏi vé tàu tại quầy',hanzi:'我想买一张去南京的高铁票，今天下午还有吗？\n有，三点二十分和五点都有。\n三点二十分的还有座位吗？\n有，请出示您的身份证。',pinyin:'Wǒ xiǎng mǎi yì zhāng qù Nánjīng de gāotiě piào, jīntiān xiàwǔ hái yǒu ma?\nYǒu, sān diǎn èrshí fēn hé wǔ diǎn dōu yǒu.\nSān diǎn èrshí fēn de hái yǒu zuòwèi ma?\nYǒu, qǐng chūshì nín de shēnfènzhèng.',meaning:'Tôi muốn mua vé tàu cao tốc đi Nam Kinh, chiều nay còn vé không?\nCòn, có chuyến 3 giờ 20 và 5 giờ.\nChuyến 3 giờ 20 còn chỗ không?\nCòn, vui lòng xuất trình giấy tờ tùy thân.',question:'Người mua muốn đi chuyến nào?',options:['3 giờ 20','4 giờ','5 giờ'],answer:0,note:'高铁 là tàu cao tốc; 座位 là chỗ ngồi; 身份证 là thẻ căn cước Trung Quốc trong bối cảnh hội thoại.'},
  { id:'lost-item',hsk:2,topic:'Đi lại',title:'Tìm đồ thất lạc',situation:'Hỏi nhân viên nhà ga',hanzi:'您好，我把黑色的背包忘在候车室了。\n里面有什么特别的东西吗？\n有一本书和一个蓝色的水瓶。\n请您先登记联系方式，我们帮您查找。',pinyin:'Nín hǎo, wǒ bǎ hēisè de bèibāo wàng zài hòuchēshì le.\nLǐmiàn yǒu shénme tèbié de dōngxi ma?\nYǒu yì běn shū hé yí ge lánsè de shuǐpíng.\nQǐng nín xiān dēngjì liánxì fāngshì, wǒmen bāng nín cházhǎo.',meaning:'Xin chào, tôi để quên ba lô màu đen ở phòng chờ.\nBên trong có đồ gì đặc biệt không?\nCó một quyển sách và một bình nước màu xanh.\nVui lòng đăng ký thông tin liên hệ trước, chúng tôi sẽ giúp tìm.',question:'Đồ vật nào được nhắc là ở trong ba lô?',options:['Một chiếc ô đỏ','Một quyển sách','Một chiếc máy ảnh'],answer:1,note:'背包 là ba lô; 候车室 là phòng chờ; 联系方式 là thông tin liên hệ.'},
  { id:'bike-share',hsk:3,topic:'Đi lại',title:'Thuê xe đạp công cộng',situation:'Hỏi cách sử dụng dịch vụ',hanzi:'附近有共享单车吗？\n有，扫一下车上的二维码就能开锁。\n骑完以后要停在指定区域，不然可能会被收取调度费。',pinyin:'Fùjìn yǒu gòngxiǎng dānchē ma?\nYǒu, sǎo yíxià chē shàng de èrwéimǎ jiù néng kāisuǒ.\nQí wán yǐhòu yào tíng zài zhǐdìng qūyù, bùrán kěnéng huì bèi shōuqǔ diàodù fèi.',meaning:'Gần đây có xe đạp dùng chung không?\nCó, quét mã QR trên xe là có thể mở khóa.\nSau khi đi xong phải đỗ trong khu vực chỉ định, nếu không có thể bị thu phí điều chuyển.',question:'Sau khi đi xe, người dùng cần làm gì?',options:['Để xe ở bất cứ đâu','Đỗ xe trong khu vực chỉ định','Mang xe về nhà'],answer:1,note:'共享单车 là xe đạp dùng chung; 二维码 là mã QR; 指定区域 là khu vực chỉ định.'},
  { id:'appointment',hsk:3,topic:'Sức khỏe',title:'Đặt lịch khám',situation:'Gọi điện đặt lịch tại phòng khám',hanzi:'您好，我想预约明天下午的门诊。\n请问您想看哪个科？\n皮肤科。我三点以后才有时间。\n好的，明天下午四点还有一个号。',pinyin:'Nín hǎo, wǒ xiǎng yùyuē míngtiān xiàwǔ de ménzhěn.\nQǐngwèn nín xiǎng kàn nǎ ge kē?\nPífūkē. Wǒ sān diǎn yǐhòu cái yǒu shíjiān.\nHǎo de, míngtiān xiàwǔ sì diǎn hái yǒu yí ge hào.',meaning:'Xin chào, tôi muốn đặt lịch khám ngoại trú chiều mai.\nBạn muốn khám khoa nào?\nKhoa da liễu. Tôi chỉ có thời gian sau ba giờ.\nĐược, chiều mai còn một lịch lúc bốn giờ.',question:'Lịch khám được đề xuất lúc mấy giờ?',options:['2 giờ','3 giờ','4 giờ'],answer:2,note:'预约 là đặt lịch; 门诊 là khám ngoại trú; 皮肤科 là khoa da liễu.'},
  { id:'project-deadline',hsk:4,topic:'Công việc',title:'Trao đổi về thời hạn dự án',situation:'Nhóm rà soát tiến độ',hanzi:'客户希望我们把方案提前两天交上去。\n目前数据分析已经完成，但设计部分还需要修改。\n我们可以先提交初稿，再在周五之前补充最终版本。',pinyin:'Kèhù xīwàng wǒmen bǎ fāng’àn tíqián liǎng tiān jiāo shàngqu.\nMùqián shùjù fēnxī yǐjīng wánchéng, dàn shèjì bùfen hái xūyào xiūgǎi.\nWǒmen kěyǐ xiān tíjiāo chūgǎo, zài zài Zhōuwǔ zhīqián bǔchōng zuìzhōng bǎnběn.',meaning:'Khách hàng muốn chúng tôi nộp phương án sớm hơn hai ngày.\nHiện phần phân tích dữ liệu đã xong, nhưng phần thiết kế vẫn cần chỉnh sửa.\nChúng ta có thể nộp bản nháp trước rồi bổ sung bản cuối trước thứ Sáu.',question:'Phần nào vẫn cần chỉnh sửa?',options:['Phân tích dữ liệu','Thiết kế','Không phần nào'],answer:1,note:'方案 là phương án; 初稿 là bản nháp; 最终版本 là phiên bản cuối.'},
  { id:'community-library',hsk:4,topic:'Xã hội',title:'Thư viện cộng đồng',situation:'Nghe thông báo hoạt động cuối tuần',hanzi:'社区图书馆本周六将举办旧书交换活动。\n参加者可以带来已经读完的书，与其他读者交换。\n活动免费，但需要提前在网上登记，名额有限。',pinyin:'Shèqū túshūguǎn běn zhōuliù jiāng jǔbàn jiùshū jiāohuàn huódòng.\nCānjiā zhě kěyǐ dài lái yǐjīng dú wán de shū, yǔ qítā dúzhě jiāohuàn.\nHuódòng miǎnfèi, dàn xūyào tíqián zài wǎngshàng dēngjì, míng’é yǒuxiàn.',meaning:'Thư viện cộng đồng tổ chức hoạt động trao đổi sách cũ vào thứ Bảy tuần này.\nNgười tham gia có thể mang sách đã đọc xong đến đổi với độc giả khác.\nHoạt động miễn phí nhưng cần đăng ký trực tuyến trước; số chỗ có hạn.',question:'Người muốn tham gia cần làm gì trước?',options:['Mua vé tại chỗ','Đăng ký trực tuyến','Gửi sách qua bưu điện'],answer:1,note:'交换活动 là hoạt động trao đổi; 提前 là trước; 名额有限 nghĩa là số chỗ có hạn.'}

];

const LISTENING_UI_KEY_PREFIX = 'linaai-listening-ui-v1:';

const topics = ['Tất cả chủ đề','Giao tiếp','Đời sống','Ăn uống','Mua sắm','Đi lại','Du lịch','Sức khỏe','Công việc','Học tập','Xã hội','Văn hóa'];
const levelLabels: Record<number,string> = {1:'Cơ bản',2:'Sơ cấp',3:'Sơ-trung cấp',4:'Trung cấp',5:'Trung-cao cấp',6:'Nâng cao'};

export const ListeningScreen: React.FC = () => {
  const { authUser, listeningProgress: reviewProgress, recordListeningQuizResult } = useApp();
  const listeningUiStorageKey = `${LISTENING_UI_KEY_PREFIX}${authUser?.id || 'guest'}`;
  const skipUiPersistRef = useRef(false);
  const [uiHydratedKey, setUiHydratedKey] = useState('');
  const [level, setLevel] = useState('all');
  const [topic, setTopic] = useState('Tất cả chủ đề');
  const [query, setQuery] = useState('');
  const [speed, setSpeed] = useState(0.85);
  const [showPinyin, setShowPinyin] = useState(true);
  const [showMeaning, setShowMeaning] = useState(true);
  const [selected, setSelected] = useState<Record<string, number>>({});
  const [revealed, setRevealed] = useState<Record<string, boolean>>({});
  const [playingId, setPlayingId] = useState<string | null>(null);
  const [playbackError, setPlaybackError] = useState('');
  const [practiceMode, setPracticeMode] = useState<'comprehension' | 'dictation' | 'ladder' | 'shadowing'>('comprehension');
  const [dictation, setDictation] = useState<Record<string, string>>({});
  const [dictationChecked, setDictationChecked] = useState<Record<string, boolean>>({});
  const [dictationFeedback, setDictationFeedback] = useState<Record<string, boolean>>({});
  const [shadowed, setShadowed] = useState<Record<string, boolean>>({});
  const [showTranscript, setShowTranscript] = useState<Record<string, boolean>>({});
  const [reviewOnly, setReviewOnly] = useState(false);

  useEffect(() => {
    skipUiPersistRef.current = true;
    setDictation({});
    setShadowed({});
    try {
      const raw = window.localStorage.getItem(listeningUiStorageKey);
      if (raw) {
        const saved = JSON.parse(raw) as { shadowed?: Record<string, boolean>; dictation?: Record<string, string> };
        if (saved.shadowed && typeof saved.shadowed === 'object') setShadowed(saved.shadowed);
        if (saved.dictation && typeof saved.dictation === 'object') setDictation(saved.dictation);
      }
    } catch {
      // Keep the learning screen usable if browser storage is unavailable.
    }
    setUiHydratedKey(listeningUiStorageKey);
  }, [listeningUiStorageKey]);

  useEffect(() => {
    if (uiHydratedKey !== listeningUiStorageKey) return;
    if (skipUiPersistRef.current) {
      skipUiPersistRef.current = false;
      return;
    }
    try {
      window.localStorage.setItem(listeningUiStorageKey, JSON.stringify({ shadowed, dictation }));
    } catch {
      // Storage restrictions must not block practice.
    }
  }, [listeningUiStorageKey, uiHydratedKey, shadowed, dictation]);

  const isDue = (id: string) => {
    const dueAt = reviewProgress[id]?.dueAt;
    return Boolean(dueAt && Number.isFinite(Date.parse(dueAt)) && Date.parse(dueAt) <= Date.now());
  };
  const dueCount = countDueListeningReviews(reviewProgress);
  const attemptedCount = lessons.filter(item => (reviewProgress[item.id]?.attempts || 0) > 0).length;
  const totalAttempts = Object.values(reviewProgress).reduce((sum, item) => sum + item.attempts, 0);
  const totalCorrect = Object.values(reviewProgress).reduce((sum, item) => sum + item.correct, 0);
  const overallAccuracy = totalAttempts ? Math.round((totalCorrect / totalAttempts) * 100) : 0;

  const visibleLessons = useMemo(() => lessons.filter(item =>
    (level === 'all' || item.hsk === Number(level)) &&
    (topic === 'Tất cả chủ đề' || item.topic === topic) &&
    (!query.trim() || (item.title + ' ' + item.situation + ' ' + item.hanzi + ' ' + item.meaning).toLowerCase().includes(query.trim().toLowerCase())) &&
    (!reviewOnly || isDue(item.id))
  ), [level, topic, query, reviewOnly, reviewProgress]);
  const score = visibleLessons.filter(item => revealed[item.id] && selected[item.id] === item.answer).length;
  const answered = visibleLessons.filter(item => revealed[item.id]).length;

  useEffect(() => () => { if ('speechSynthesis' in window) window.speechSynthesis.cancel(); }, []);

  const checkAnswer = (item: ListeningItem) => {
    const choice = selected[item.id];
    if (choice === undefined || revealed[item.id]) return;
    const correct = choice === item.answer;
    setRevealed(previous => ({ ...previous, [item.id]: true }));
    recordListeningQuizResult(item.id, correct);
  };

  const speak = (item: ListeningItem) => {
    if (typeof window.speechSynthesis === 'undefined') {
      setPlayingId(null);
      setPlaybackError('Trình duyệt này chưa hỗ trợ phát giọng nói. Hãy thử Chrome hoặc Edge bản mới.');
      return;
    }
    setPlaybackError('');
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(item.hanzi.replace(/\n/g, '。'));
    utterance.lang = 'zh-CN';
    utterance.rate = speed;
    const voices = window.speechSynthesis.getVoices();
    const chineseVoice = voices.find(voice => voice.lang.toLowerCase().startsWith('zh-cn')) || voices.find(voice => voice.lang.toLowerCase().startsWith('zh'));
    if (chineseVoice) utterance.voice = chineseVoice;
    utterance.onstart = () => setPlayingId(item.id);
    utterance.onend = () => setPlayingId(null);
    utterance.onerror = () => { setPlayingId(null); setPlaybackError('Không phát được giọng đọc trên thiết bị này. Hãy kiểm tra cài đặt giọng tiếng Trung.'); };
    setPlayingId(item.id);
    window.speechSynthesis.speak(utterance);
  };
  const stopAudio = () => { if ('speechSynthesis' in window) window.speechSynthesis.cancel(); setPlayingId(null); };

  return (
    <div className="mx-auto max-w-[1500px] px-4 py-5 sm:px-6 lg:px-8 lg:py-8 pb-28 md:pb-10 space-y-6">
      <header className="flex flex-col gap-5 xl:flex-row xl:items-end xl:justify-between">
        <div>
          <div className="inline-flex items-center gap-2 rounded-full border border-amber-200 bg-amber-50 px-3 py-1 text-xs font-semibold text-amber-800 dark:border-amber-900/60 dark:bg-amber-950/30 dark:text-amber-300"><Headphones className="h-3.5 w-3.5" /> LISTENING LAB · 听力练习</div>
          <h1 className="mt-3 text-3xl font-bold tracking-tight text-stone-900 dark:text-stone-50 lg:text-4xl">Luyện nghe tiếng Trung</h1>
          <p className="mt-2 max-w-3xl text-sm leading-6 text-stone-500 dark:text-stone-400">Tình huống giao tiếp đời thường, thông báo, công việc và học tập từ HSK 1–6. Nghe trước, trả lời câu hỏi rồi mở bản chữ để tự kiểm tra.</p>
          <div className="mt-3 inline-flex items-start gap-2 rounded-xl border border-blue-200 bg-blue-50 px-3 py-2 text-xs leading-5 text-blue-900 dark:border-blue-900/60 dark:bg-blue-950/30 dark:text-blue-200"><Volume2 className="mt-0.5 h-4 w-4 shrink-0" /><span><strong>Minh bạch âm thanh:</strong> giọng phát hiện tại là TTS tiếng Trung do trình duyệt/thiết bị tạo, không phải bản ghi âm người bản ngữ. Các bài là hội thoại học tập được biên soạn, không giả làm tin tức hay dữ liệu trực tiếp.</span></div>
        </div>
        <div className="grid grid-cols-3 gap-2 sm:min-w-[360px]">
          <div className="rounded-2xl border border-stone-200 bg-white p-3 dark:border-stone-800 dark:bg-stone-900"><div className="text-xs text-stone-500">Bài nghe</div><div className="mt-1 text-2xl font-black text-stone-900 dark:text-stone-100">{lessons.length}</div></div>
          <div className="rounded-2xl border border-stone-200 bg-white p-3 dark:border-stone-800 dark:bg-stone-900"><div className="text-xs text-stone-500">Cấp độ</div><div className="mt-1 text-2xl font-black text-stone-900 dark:text-stone-100">HSK 1–6</div></div>
          <div className="rounded-2xl border border-stone-200 bg-white p-3 dark:border-stone-800 dark:bg-stone-900"><div className="text-xs text-stone-500">Đúng trong lọc</div><div className="mt-1 text-2xl font-black text-stone-900 dark:text-stone-100">{score}/{answered}</div></div>
        </div>
      </header>

      <section className="rounded-3xl border border-stone-200 bg-white p-4 dark:border-stone-800 dark:bg-stone-900">
        <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
          <div><h2 className="font-bold text-stone-900 dark:text-stone-100">Chọn cách luyện nghe</h2><p className="mt-1 text-xs leading-5 text-stone-500">Cùng một bài có thể luyện nhiều kỹ năng. Chế độ không tự chấm phát âm hoặc giả lập điểm giọng nói.</p></div>
          <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
            {([{id:'comprehension',label:'Nghe hiểu',hint:'Nghe và trả lời'},{id:'dictation',label:'Chép chính tả',hint:'Nghe rồi gõ'},{id:'ladder',label:'Nghe theo tầng',hint:'Ẩn dần trợ giúp'},{id:'shadowing',label:'Shadowing',hint:'Nghe rồi nhại lại'}] as const).map(mode=><button key={mode.id} type="button" onClick={()=>setPracticeMode(mode.id)} aria-pressed={practiceMode===mode.id} className={`min-h-14 rounded-xl border px-3 py-2 text-left transition ${practiceMode===mode.id?'border-amber-400 bg-amber-50 text-amber-950 dark:border-amber-700 dark:bg-amber-950/30 dark:text-amber-100':'border-stone-200 text-stone-600 hover:border-stone-300 dark:border-stone-700 dark:text-stone-300'}`}><span className="block text-xs font-bold">{mode.label}</span><span className="mt-1 block text-[10px] opacity-75">{mode.hint}</span></button>)}
          </div>
        </div>
        {practiceMode==='dictation'&&<p className="mt-3 rounded-xl bg-blue-50 px-3 py-2 text-xs leading-5 text-blue-900 dark:bg-blue-950/30 dark:text-blue-200">Bài chép chính tả so sánh văn bản bạn nhập với lời thoại mẫu sau khi bạn bấm kiểm tra. Dấu câu và khoảng trắng được chuẩn hóa; đây không phải đánh giá năng lực tổng quát.</p>}
        {practiceMode==='ladder'&&<p className="mt-3 rounded-xl bg-violet-50 px-3 py-2 text-xs leading-5 text-violet-900 dark:bg-violet-950/30 dark:text-violet-200">Lộ trình gợi ý: nghe không xem chữ → bật chữ Hán → bật pinyin → xem nghĩa tiếng Việt → trả lời câu hỏi. Dùng công tắc trong bộ lọc để tăng hoặc giảm trợ giúp.</p>}
        {practiceMode==='shadowing'&&<p className="mt-3 rounded-xl bg-emerald-50 px-3 py-2 text-xs leading-5 text-emerald-900 dark:bg-emerald-950/30 dark:text-emerald-200">Cách tập: nghe trọn đoạn, dừng một nhịp, đọc nhại thành tiếng rồi phát lại để tự so sánh. Trang web không thu âm hoặc chấm điểm phát âm tự động.</p>}
      </section>

      <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
        <div className="rounded-2xl border border-stone-200 bg-white p-4 dark:border-stone-800 dark:bg-stone-900"><p className="text-xs text-stone-500">Bài đã luyện</p><p className="mt-1 text-2xl font-black">{attemptedCount}<span className="ml-1 text-sm font-semibold text-stone-400">/ {lessons.length}</span></p><p className="mt-1 text-xs text-stone-500">Đã có ít nhất một lần kiểm tra</p></div>
        <div className="rounded-2xl border border-stone-200 bg-white p-4 dark:border-stone-800 dark:bg-stone-900"><p className="text-xs text-stone-500">Độ chính xác tích lũy</p><p className="mt-1 text-2xl font-black">{overallAccuracy}%</p><p className="mt-1 text-xs text-stone-500">{totalCorrect}/{totalAttempts} lượt trả lời đúng</p></div>
        <div className="rounded-2xl border border-stone-200 bg-white p-4 dark:border-stone-800 dark:bg-stone-900"><p className="text-xs text-stone-500">Bài đến hạn ôn</p><p className="mt-1 text-2xl font-black">{dueCount}</p><p className="mt-1 text-xs text-stone-500">Sai: nhắc lại sau 10 phút; đúng liên tiếp: giãn dần 1–14 ngày</p></div>
        <div className="flex flex-col justify-between gap-2 rounded-2xl border border-stone-200 bg-white p-4 dark:border-stone-800 dark:bg-stone-900"><div><p className="text-sm font-bold">Ôn tập ngắt quãng</p><p className="mt-1 text-xs leading-5 text-stone-500">Tiến độ được lưu trong trình duyệt hiện tại, chưa đồng bộ giữa thiết bị.</p></div><button type="button" onClick={()=>setReviewOnly(v=>!v)} aria-pressed={reviewOnly} className={reviewOnly ? 'min-h-10 rounded-xl border border-amber-400 bg-amber-50 px-3 text-xs font-bold text-amber-900 dark:bg-amber-950/30 dark:text-amber-200' : 'min-h-10 rounded-xl border border-stone-200 px-3 text-xs font-bold text-stone-700 dark:border-stone-700 dark:text-stone-300'}>{reviewOnly?'Đang xem bài đến hạn · Tắt lọc':'Ôn bài đến hạn'} ({dueCount})</button></div>
      </section>

      <div className="grid gap-6 xl:grid-cols-[280px_minmax(0,1fr)]">
        <aside className="h-fit space-y-5 rounded-3xl border border-stone-200 bg-white p-4 dark:border-stone-800 dark:bg-stone-900 xl:sticky xl:top-5">
          <div className="flex items-center gap-2 text-sm font-bold"><Settings2 className="h-4 w-4 text-amber-600" /> Bộ lọc luyện nghe</div>
          <label className="block text-xs font-semibold text-stone-600 dark:text-stone-300">Tìm theo nội dung
            <span className="relative mt-2 block"><Search className="absolute left-3 top-3 h-4 w-4 text-stone-400" /><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Ví dụ: khách sạn, cuộc họp..." className="min-h-10 w-full rounded-xl border border-stone-200 bg-stone-50 pl-9 pr-3 text-sm dark:border-stone-700 dark:bg-stone-800" /></span>
          </label>
          <label className="block text-xs font-semibold text-stone-600 dark:text-stone-300">Cấp độ HSK
            <select value={level} onChange={e=>setLevel(e.target.value)} className="mt-2 min-h-11 w-full rounded-xl border border-stone-200 bg-stone-50 px-3 text-sm dark:border-stone-700 dark:bg-stone-800"><option value="all">Tất cả cấp độ</option>{[1,2,3,4,5,6].map(n=><option key={n} value={String(n)}>HSK {n} · {levelLabels[n]}</option>)}</select>
          </label>
          <div><div className="mb-2 text-xs font-semibold text-stone-600 dark:text-stone-300">Chủ đề</div><div className="flex flex-wrap gap-2 xl:flex-col">{topics.map(t=><button key={t} type="button" onClick={()=>setTopic(t)} className={`min-h-9 rounded-xl border px-3 text-left text-xs font-semibold transition ${topic===t?'border-amber-400 bg-amber-50 text-amber-900 dark:border-amber-800 dark:bg-amber-950/30 dark:text-amber-200':'border-stone-200 text-stone-600 hover:border-stone-300 dark:border-stone-700 dark:text-stone-300'}`}>{t}</button>)}</div></div>
          <div className="border-t border-stone-100 pt-4 dark:border-stone-800"><div className="mb-3 text-xs font-semibold text-stone-600 dark:text-stone-300">Tốc độ TTS <span className="text-amber-700 dark:text-amber-300">{speed.toFixed(2)}×</span></div><input aria-label="Tốc độ giọng đọc" type="range" min="0.65" max="1.15" step="0.05" value={speed} onChange={e=>setSpeed(Number(e.target.value))} className="w-full accent-amber-600" /><div className="mt-1 flex justify-between text-[10px] text-stone-400"><span>Chậm</span><span>Tự nhiên</span></div></div>
          <div className="flex flex-wrap gap-2"><button type="button" onClick={()=>setShowPinyin(v=>!v)} aria-pressed={showPinyin} className={`min-h-9 rounded-lg border px-3 text-xs font-semibold ${showPinyin?'border-amber-300 bg-amber-50 text-amber-800 dark:border-amber-900 dark:bg-amber-950/30 dark:text-amber-300':'border-stone-200 text-stone-500 dark:border-stone-700'}`}>Pinyin {showPinyin?'bật':'tắt'}</button><button type="button" onClick={()=>setShowMeaning(v=>!v)} aria-pressed={showMeaning} className={`min-h-9 rounded-lg border px-3 text-xs font-semibold ${showMeaning?'border-amber-300 bg-amber-50 text-amber-800 dark:border-amber-900 dark:bg-amber-950/30 dark:text-amber-300':'border-stone-200 text-stone-500 dark:border-stone-700'}`}>Nghĩa Việt {showMeaning?'bật':'tắt'}</button></div>
          <button type="button" onClick={()=>{setLevel('all');setTopic('Tất cả chủ đề');setQuery('');setShowPinyin(true);setShowMeaning(true);setReviewOnly(false);}} className="inline-flex min-h-10 w-full items-center justify-center gap-2 rounded-xl border border-stone-200 px-3 text-xs font-semibold text-stone-600 hover:bg-stone-50 dark:border-stone-700 dark:text-stone-300 dark:hover:bg-stone-800"><RotateCcw className="h-3.5 w-3.5" /> Xóa bộ lọc</button>
        </aside>

        <main className="min-w-0 space-y-4">
          <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="text-lg font-bold text-stone-900 dark:text-stone-100">{topic==='Tất cả chủ đề'?'Thư viện bài nghe':topic}</h2><p className="text-xs text-stone-500">Hiển thị {visibleLessons.length} / {lessons.length} bài · chọn đáp án để kiểm tra</p></div><button type="button" onClick={()=>{setSelected({});setRevealed({});setShowTranscript({});stopAudio();}} className="inline-flex min-h-10 items-center justify-center gap-2 self-start rounded-xl border border-stone-200 px-3 text-xs font-semibold text-stone-600 dark:border-stone-700 dark:text-stone-300"><RotateCcw className="h-3.5 w-3.5" /> Làm lại kết quả phiên này</button></div>
          {visibleLessons.length===0 ? <div className="rounded-3xl border border-dashed border-stone-300 p-10 text-center dark:border-stone-700"><BookOpen className="mx-auto h-8 w-8 text-stone-400" /><p className="mt-3 font-semibold">Không tìm thấy bài phù hợp</p><p className="mt-1 text-sm text-stone-500">Thử từ khóa hoặc chủ đề khác nhé.</p></div> :
          <div className="grid gap-4 2xl:grid-cols-2">
            {visibleLessons.map((item,index)=>{
              const isRevealed=Boolean(revealed[item.id]); const choice=selected[item.id]; const isCorrect=choice===item.answer;
              return <article key={item.id} className="flex min-w-0 flex-col overflow-hidden rounded-3xl border border-stone-200 bg-white dark:border-stone-800 dark:bg-stone-900">
                <div className="border-b border-stone-100 p-4 dark:border-stone-800"><div className="flex flex-wrap items-center gap-2"><span className="rounded-lg bg-amber-50 px-2 py-1 text-[10px] font-bold uppercase tracking-wide text-amber-800 dark:bg-amber-950/40 dark:text-amber-300">HSK {item.hsk} · {levelLabels[item.hsk]}</span><span className="rounded-lg bg-stone-100 px-2 py-1 text-[10px] font-semibold text-stone-600 dark:bg-stone-800 dark:text-stone-300">{item.topic}</span>{isRevealed&&<span className="ml-auto inline-flex items-center gap-1 text-[10px] font-bold text-emerald-700 dark:text-emerald-300"><CheckCircle2 className="h-3.5 w-3.5"/> Đã làm</span>}</div><h3 className="mt-2 text-lg font-bold text-stone-900 dark:text-stone-100">{item.title}</h3><p className="mt-1 text-xs text-stone-500 dark:text-stone-400">{item.situation}</p></div>
                <div className="flex flex-1 flex-col p-4">
                  <div className="rounded-2xl bg-[#faf8f5] p-3 dark:bg-stone-950/70">
                    <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-3"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-amber-600 text-white"><AudioLines className="h-5 w-5"/></div><div><div className="text-sm font-bold">Nghe đoạn hội thoại</div><div className="text-[11px] text-stone-500">TTS · {speed.toFixed(2)}×</div></div></div><div className="flex gap-2"><button type="button" onClick={()=>playingId===item.id?stopAudio():speak(item)} className="inline-flex min-h-10 flex-1 items-center justify-center gap-2 rounded-xl bg-stone-900 px-3 text-xs font-bold text-white hover:bg-amber-700 dark:bg-stone-100 dark:text-stone-900">{playingId===item.id?<Pause className="h-4 w-4"/>:<Play className="h-4 w-4"/>}{playingId===item.id?'Dừng':'Phát'}</button><button type="button" onClick={()=>setShowTranscript(p=>({...p,[item.id]:true}))} className="min-h-10 rounded-xl border border-stone-200 px-3 text-xs font-semibold text-stone-700 dark:border-stone-700 dark:text-stone-300">Xem lời thoại</button></div></div>
                    {(isRevealed||showTranscript[item.id])&&<div className="mt-3 space-y-2 border-t border-stone-200 pt-3 dark:border-stone-800"><p className="whitespace-pre-line text-base font-semibold leading-relaxed text-stone-900 dark:text-stone-100">{item.hanzi}</p>{showPinyin&&<p className="whitespace-pre-line text-xs leading-6 text-amber-800 dark:text-amber-300">{item.pinyin}</p>}{showMeaning&&<p className="whitespace-pre-line text-xs leading-6 text-stone-600 dark:text-stone-300">{item.meaning}</p>}</div>}
                  </div>
                  {practiceMode==='dictation'&&<div className="mt-3 space-y-2">
                    <label className="block text-xs font-semibold text-stone-700 dark:text-stone-300">Gõ lại đoạn tiếng Trung bạn nghe
                      <textarea value={dictation[item.id]||''} onChange={e=>{setDictation(p=>({...p,[item.id]:e.target.value}));setDictationChecked(p=>({...p,[item.id]:false}));}} rows={3} placeholder="Nhập chữ Hán tại đây…" className="mt-2 w-full rounded-xl border border-stone-200 bg-white p-3 text-sm leading-6 dark:border-stone-700 dark:bg-stone-950" />
                    </label>
                    <button type="button" disabled={!(dictation[item.id]||'').trim()} onClick={()=>{const normalize=(v:string)=>v.replace(/[，。！？、；：,.!?;:\s]/g,'');setDictationFeedback(p=>({...p,[item.id]:normalize(dictation[item.id]||'')===normalize(item.hanzi)}));setDictationChecked(p=>({...p,[item.id]:true}));}} className="min-h-10 rounded-xl bg-amber-700 px-4 text-xs font-bold text-white disabled:opacity-40">Kiểm tra bản chép</button>
                    {dictationChecked[item.id]&&<p role="status" className={`rounded-xl p-3 text-xs leading-5 ${dictationFeedback[item.id]?'bg-emerald-50 text-emerald-800 dark:bg-emerald-950/30 dark:text-emerald-200':'bg-amber-50 text-amber-900 dark:bg-amber-950/30 dark:text-amber-200'}`}>{dictationFeedback[item.id]?'Khớp với lời thoại mẫu sau khi chuẩn hóa dấu câu.':'Chưa khớp hoàn toàn. Xem lời thoại mẫu để đối chiếu từng cụm từ.'} Đây chỉ là so khớp văn bản, không đo phát âm.</p>}
                  </div>}
                  {practiceMode==='shadowing'&&<div className="mt-3 rounded-xl border border-emerald-200 p-3 dark:border-emerald-900/50"><p className="text-xs font-semibold">Tự luyện shadowing</p><p className="mt-1 text-xs leading-5 text-stone-500">1. Phát đoạn nghe. 2. Nhại lại ngay sau câu. 3. Đánh dấu đã tự luyện sau khi hoàn thành.</p><button type="button" onClick={()=>setShadowed(p=>({...p,[item.id]:!p[item.id]}))} className={`mt-2 min-h-9 rounded-lg border px-3 text-xs font-semibold ${shadowed[item.id]?'border-emerald-400 bg-emerald-50 text-emerald-800 dark:bg-emerald-950/30 dark:text-emerald-200':'border-stone-200 text-stone-600 dark:border-stone-700 dark:text-stone-300'}`}>{shadowed[item.id]?'Đã tự luyện ✓':'Đánh dấu đã tự luyện'}</button></div>}
                  {playbackError&&<p role="status" className="mt-2 text-xs leading-5 text-rose-700 dark:text-rose-300">{playbackError}</p>}
                  <div className="mt-4 flex items-start gap-2 text-sm font-bold"><CircleHelp className="mt-0.5 h-4 w-4 shrink-0 text-amber-600"/><span>{item.question}</span></div>
                  <div className="mt-3 grid gap-2">{item.options.map((option,i)=><button key={option} type="button" disabled={isRevealed} onClick={()=>setSelected(p=>({...p,[item.id]:i}))} className={`flex min-h-10 items-center gap-2 rounded-xl border px-3 py-2 text-left text-xs transition ${choice===i?'border-amber-400 bg-amber-50 text-amber-950 dark:border-amber-700 dark:bg-amber-950/30 dark:text-amber-100':'border-stone-200 hover:border-stone-300 dark:border-stone-700 dark:hover:border-stone-600'} ${isRevealed&&i===item.answer?'!border-emerald-400 !bg-emerald-50 dark:!bg-emerald-950/30':''}`}><span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-md bg-stone-100 text-[10px] font-bold dark:bg-stone-800">{String.fromCharCode(65+i)}</span><span className="flex-1">{option}</span>{isRevealed&&i===item.answer&&<CheckCircle2 className="h-4 w-4 text-emerald-600"/>}</button>)}</div>
                  {isRevealed?<div className={`mt-3 rounded-xl p-3 text-xs leading-5 ${choice===undefined?'bg-blue-50 text-blue-900 dark:bg-blue-950/30 dark:text-blue-200':isCorrect?'bg-emerald-50 text-emerald-800 dark:bg-emerald-950/30 dark:text-emerald-200':'bg-amber-50 text-amber-900 dark:bg-amber-950/30 dark:text-amber-200'}`}><div className="font-bold">{choice===undefined?'Đã mở lời thoại':isCorrect?'Chính xác!':'Hãy nghe lại và ghi nhớ nhé.'}</div><p className="mt-1">{item.note}</p></div>:<button type="button" disabled={choice===undefined} onClick={()=>checkAnswer(item)} className="mt-3 min-h-10 w-full rounded-xl bg-amber-700 px-4 text-xs font-bold text-white transition hover:bg-amber-800 disabled:cursor-not-allowed disabled:opacity-40">Kiểm tra đáp án</button>}
                </div>
              </article>;
            })}
          </div>}
        </main>
      </div>
      <footer className="rounded-3xl border border-amber-200 bg-amber-50 p-4 text-xs leading-5 text-stone-700 dark:border-amber-900/50 dark:bg-amber-950/20 dark:text-stone-300"><strong className="text-stone-900 dark:text-stone-100">Lưu ý về độ tin cậy:</strong> Các đoạn hội thoại và câu hỏi là nội dung học tập biên soạn, không phải trích dẫn từ đề thi HSK chính thức hay bản tin thật. Âm thanh được tạo bởi TTS có sẵn trên máy; chất lượng và giọng vùng miền phụ thuộc trình duyệt/hệ điều hành. Muốn dùng audio người bản ngữ, cần tích hợp nguồn ghi âm có giấy phép và ghi rõ xuất xứ từng bài.</footer>
    </div>
  );
};
